import { inject } from '@angular/core';
import { of } from 'rxjs';

import { BaseLogicService } from '../../logic/service/base-logic.service';

export class BaseApiService<TData> {
  private readonly service: BaseLogicService<TData>;

  constructor(private readonly type: typeof BaseLogicService<TData>) {
    this.service = inject(type);
  }

  select(id: number) {
    return of(this.service.select(id));
  }

  deselect(id: number) {
    return of(this.service.deselect(id));
  }

  create(parentId: number | undefined, data: TData) {
    return of(this.service.create(parentId, data));
  }

  readById(id: number) {
    return of(this.service.readById(id));
  }

  readByParentId(parentId: number | undefined) {
    return of(this.service.readByParentId(parentId));
  }

  update(id: number, data: TData) {
    return of(this.service.update(id, data));
  }

  delete(id: number) {
    return of(this.service.delete(id));
  }

  moveUp(id: number) {
    return of(this.service.moveUp(id));
  }

  moveDown(id: number) {
    return of(this.service.moveDown(id));
  }
}

import { BaseDatabaseModel } from '../model/base/base-database.model';

export class BaseDatabaseData<TData> {
  constructor(private items: BaseDatabaseModel<TData>[]) {}

  setItems(items: BaseDatabaseModel<TData>[]) {
    this.items = structuredClone(items);
  }

  getItems() {
    return structuredClone(this.items);
  }
}

import { inject } from '@angular/core';

import { BaseDatabaseData } from '../data/base-database.data';
import { BaseDatabaseModel } from '../model/base/base-database.model';

export class BaseDatabaseService<TData> {
  protected readonly service: BaseDatabaseData<TData>;

  constructor(private readonly type: typeof BaseDatabaseData<TData>) {
    this.service = inject(type);
  }

  create(itemToCreate: BaseDatabaseModel<TData>) {
    const items = this.service.getItems();
    items.push(itemToCreate);
    this.service.setItems(items);
  }

  readAll() {
    return structuredClone(this.service.getItems());
  }

  readById(id: number) {
    return this.readAll().find((item) => item.metadata.id === id);
  }

  readByParentId(parentId: number) {
    return this.readAll().filter((item) => {
      if (item.metadata.parentId === undefined) {
        return false;
      }
      return item.metadata.parentId === parentId;
    });
  }

  update(itemToUpdate: BaseDatabaseModel<TData>) {
    const items = this.readAll().map((item) => {
      if (item.metadata.id === itemToUpdate.metadata.id) {
        return itemToUpdate;
      }
      return item;
    });
    this.service.setItems(items);
  }

  delete(id: number) {
    const items = this.readAll().filter((item) => item.metadata.id !== id);
    this.service.setItems(items);
  }

  getItems() {
    return this.service.getItems();
  }
}

import { inject } from '@angular/core';

import { BaseDatabaseService } from '../../database/service/base-database.service';
import { BaseDatabaseModel } from '../../database/model/base/base-database.model';
import { ResponseLogicModel } from '../model/response-logic.model';

export class BaseLogicService<TData> {
  private readonly service: BaseDatabaseService<TData>;

  private nextId: number;

  constructor(private readonly type: typeof BaseDatabaseService<TData>) {
    this.service = inject(type);
    this.nextId = this.service.getItems().length;
  }

  select(id: number): ResponseLogicModel<BaseDatabaseModel<TData> | undefined> {
    const itemToSelect = this.service.readById(id);
    if (itemToSelect === undefined) {
      return {
        success: false,
        message: 'Failed to select the item because it does not exist.',
        body: undefined,
      };
    }
    const items =
      itemToSelect.metadata.parentId === undefined
        ? this.service.readAll()
        : this.service.readByParentId(itemToSelect.metadata.parentId);
    items.forEach((item) => {
      if (item.metadata.id === itemToSelect.metadata.id) {
        item.metadata.isSelected = true;
      } else {
        item.metadata.isSelected = false;
      }
      this.service.update(item);
    });
    const currentItem = this.service.readById(id);
    return {
      success: true,
      message: 'The item was selected correctly.',
      body: currentItem,
    };
  }

  deselect(
    id: number,
  ): ResponseLogicModel<BaseDatabaseModel<TData> | undefined> {
    const itemToDeselect = this.service.readById(id);
    if (itemToDeselect === undefined) {
      return {
        success: false,
        message: 'Failed to deselect the item because it does not exist.',
        body: undefined,
      };
    }
    itemToDeselect.metadata.isSelected = false;
    this.service.update(itemToDeselect);
    return {
      success: true,
      message: 'The item was deselected correctly.',
      body: itemToDeselect,
    };
  }

  create(
    parentId: number | undefined,
    data: TData,
  ): ResponseLogicModel<BaseDatabaseModel<TData>> {
    const items =
      parentId === undefined
        ? this.service.readAll()
        : this.service.readByParentId(parentId);
    const lastOrder = items.reduce((acc: number, curr) => {
      if (curr.metadata.order > acc) {
        acc = curr.metadata.order;
      }
      return acc;
    }, 0);
    const itemToCreate: BaseDatabaseModel<TData> = {
      data,
      metadata: {
        id: this.nextId,
        parentId,
        order: lastOrder + 1,
        isSelected: false,
      },
    };
    this.nextId++;
    this.service.create(itemToCreate);
    return {
      success: true,
      message: 'The item was created correctly.',
      body: itemToCreate,
    };
  }

  readById(
    id: number,
  ): ResponseLogicModel<BaseDatabaseModel<TData> | undefined> {
    const item = this.service.readById(id);
    if (item === undefined) {
      return {
        success: false,
        message: 'Failed to read the item.',
        body: undefined,
      };
    }
    return {
      success: true,
      message: 'The item was read correctly.',
      body: item,
    };
  }

  readByParentId(
    parentId: number | undefined,
  ): ResponseLogicModel<BaseDatabaseModel<TData>[]> {
    const items =
      parentId === undefined
        ? this.service.readAll()
        : this.service.readByParentId(parentId);
    if (items.length === 0) {
      return {
        success: false,
        message: 'The list of items is empty.',
        body: [],
      };
    }
    return {
      success: true,
      message: 'The items was read correctly.',
      body: items,
    };
  }

  update(
    id: number,
    data: TData,
  ): ResponseLogicModel<BaseDatabaseModel<TData> | undefined> {
    const itemToUpdate = this.service.readById(id);
    if (itemToUpdate === undefined) {
      return {
        success: false,
        message: 'Failed to update the item because it does not exist.',
        body: undefined,
      };
    }
    itemToUpdate.data = structuredClone(data);
    this.service.update(itemToUpdate);
    return {
      success: true,
      message: 'The item was updated correctly.',
      body: itemToUpdate,
    };
  }

  delete(id: number): ResponseLogicModel<BaseDatabaseModel<TData> | undefined> {
    const itemToDelete = this.service.readById(id);
    if (itemToDelete === undefined) {
      return {
        success: false,
        message: 'Failed to move up the item because it does not exist.',
        body: undefined,
      };
    }
    const { parentId } = itemToDelete.metadata;
    this.service.delete(itemToDelete.metadata.id);
    const itemsToUpdate =
      parentId === undefined
        ? this.service.readAll()
        : this.service.readByParentId(parentId);
    itemsToUpdate
      .sort((prev, next) => prev.metadata.order - next.metadata.order)
      .map((itemToUpdate, index) => {
        itemToUpdate.metadata.order = index;
        return itemToUpdate;
      })
      .forEach((itemToUpdate) => this.service.update(itemToUpdate));
    return {
      success: true,
      message: 'The item was deleted correctly.',
      body: itemToDelete,
    };
  }

  moveUp(id: number): ResponseLogicModel<BaseDatabaseModel<TData> | undefined> {
    const itemToMoveUp = this.service.readById(id);
    if (itemToMoveUp === undefined) {
      return {
        success: false,
        message: 'Failed to move up the item because it does not exist.',
        body: undefined,
      };
    }
    if (itemToMoveUp.metadata.order === 0) {
      return {
        success: false,
        message: 'Failed to move up the item because it is the first element.',
        body: undefined,
      };
    }
    const items =
      itemToMoveUp.metadata.parentId === undefined
        ? this.service.readAll()
        : this.service.readByParentId(itemToMoveUp.metadata.parentId);
    const prevItem = items.find(
      (item) => item.metadata.order === itemToMoveUp.metadata.order - 1,
    );
    if (prevItem === undefined) {
      return {
        success: false,
        message:
          'Failed to move up the item because the previous item does not exist.',
        body: undefined,
      };
    }
    const itemToMoveUpOrder = itemToMoveUp.metadata.order;
    itemToMoveUp.metadata.order = prevItem.metadata.order;
    prevItem.metadata.order = itemToMoveUpOrder;
    this.service.update(itemToMoveUp);
    this.service.update(prevItem);
    return {
      success: true,
      message: 'The item was moved up correctly.',
      body: itemToMoveUp,
    };
  }

  moveDown(
    id: number,
  ): ResponseLogicModel<BaseDatabaseModel<TData> | undefined> {
    const itemToMoveDown = this.service.readById(id);
    if (itemToMoveDown === undefined) {
      return {
        success: false,
        message: 'Failed to move down the item because it does not exist.',
        body: undefined,
      };
    }
    const items =
      itemToMoveDown.metadata.parentId === undefined
        ? this.service.readAll()
        : this.service.readByParentId(itemToMoveDown.metadata.parentId);
    const lastOrder = items.reduce((acc: number, curr) => {
      if (curr.metadata.order > acc) {
        acc = curr.metadata.order;
      }
      return acc;
    }, 0);
    if (itemToMoveDown.metadata.order === lastOrder) {
      return {
        success: false,
        message: 'Failed to move down the item because it is the last element.',
        body: undefined,
      };
    }
    const nextItem = items.find(
      (item) => item.metadata.order === itemToMoveDown.metadata.order + 1,
    );
    if (nextItem === undefined) {
      return {
        success: false,
        message:
          'Failed to move down the item because the next item does not exist.',
        body: undefined,
      };
    }
    const itemToMoveDownOrder = itemToMoveDown.metadata.order;
    itemToMoveDown.metadata.order = nextItem.metadata.order;
    nextItem.metadata.order = itemToMoveDownOrder;
    this.service.update(itemToMoveDown);
    this.service.update(nextItem);
    return {
      success: true,
      message: 'The item was moved down correctly.',
      body: itemToMoveDown,
    };
  }
}

import { inject } from '@angular/core';
import { Store } from '@ngxs/store';
import { filter, map, of, switchMap } from 'rxjs';

import { BaseApiService } from '../api/service/base-api.service';
import { BaseStoreAction } from '../store/action/base-store.action';
import {
  BaseStoreColumnModel,
  BaseStoreModel,
} from '../store/model/base-store.model';
import { BaseDatabaseModel } from '../database/model/base/base-database.model';

export class BaseService<TData> {
  baseApiService: BaseApiService<TData>;

  store = inject(Store);

  constructor(
    private readonly token: typeof BaseApiService<TData>,
    private readonly baseGetStatus: (state: BaseStoreModel<TData>) => {
      success: boolean;
      message: string;
    },
    private readonly baseGetIsLoading: (
      state: BaseStoreModel<TData>,
    ) => boolean,
    private readonly baseGetItems: (
      state: BaseStoreModel<TData>,
    ) => BaseDatabaseModel<TData>[],
    private readonly baseGetSelectedItem: (
      state: BaseStoreModel<TData>,
    ) => BaseDatabaseModel<TData> | undefined,
    private readonly baseGetColumns: (
      state: BaseStoreModel<TData>,
    ) => BaseStoreColumnModel[],
    private readonly baseSetStatus: typeof BaseStoreAction.SetStatus,
    private readonly baseSetIsLoading: typeof BaseStoreAction.SetIsLoading,
    private readonly baseSetItems: typeof BaseStoreAction.SetItems<TData>,
  ) {
    this.baseApiService = inject(token);
  }

  getStatus() {
    return this.store.select(this.baseGetStatus);
  }

  getIsLoading() {
    return this.store.select(this.baseGetIsLoading);
  }

  getItems() {
    return this.store.select(this.baseGetItems);
  }

  getSelectedItem() {
    return this.store.select(this.baseGetSelectedItem);
  }

  getColumns() {
    return this.store.select(this.baseGetColumns);
  }

  select(id: number) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.select(id)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        if (!success && body === undefined) {
          this.store.dispatch(new this.baseSetIsLoading(false));
        }
        return of(body);
      }),
      filter((body) => body !== undefined),
      switchMap((body) =>
        this.baseApiService.readByParentId(body.metadata.parentId),
      ),
      switchMap((response) => of(response.body)),
      switchMap((items) => this.store.dispatch(new this.baseSetItems(items))),
      switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false))),
    );
  }

  deselect(id: number) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.deselect(id)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        if (!success && body === undefined) {
          this.store.dispatch(new this.baseSetIsLoading(false));
        }
        return of(body);
      }),
      filter((body) => body !== undefined),
      switchMap((body) =>
        this.baseApiService.readByParentId(body.metadata.parentId),
      ),
      switchMap((response) => of(response.body)),
      switchMap((items) => this.store.dispatch(new this.baseSetItems(items))),
      switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false))),
    );
  }

  create(parentId: number | undefined, data: TData) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.create(parentId, data)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        return of(body);
      }),
      switchMap((body) =>
        this.baseApiService.readByParentId(body.metadata.parentId),
      ),
      switchMap((response) => of(response.body)),
      switchMap((items) => this.store.dispatch(new this.baseSetItems(items))),
      switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false))),
    );
  }

  readById(id: number) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.readById(id)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        if (!success && body === undefined) {
          this.store.dispatch(new this.baseSetIsLoading(false));
        }
        return of(body);
      }),
      switchMap((body) =>
        this.store
          .dispatch(new this.baseSetIsLoading(false))
          .pipe(map(() => body)),
      ),
    );
  }

  readByParentId(parentId: number | undefined) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.readByParentId(parentId)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        return of(body);
      }),
      switchMap((items) => this.store.dispatch(new this.baseSetItems(items))),
      switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false))),
    );
  }

  update(id: number, data: TData) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.update(id, data)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        if (!success && body === undefined) {
          this.store.dispatch(new this.baseSetIsLoading(false));
        }
        return of(body);
      }),
      filter((body) => body !== undefined),
      switchMap((body) =>
        this.baseApiService.readByParentId(body.metadata.parentId),
      ),
      switchMap((response) =>
        this.store.dispatch(new this.baseSetItems(response.body)),
      ),
      switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false))),
    );
  }

  delete(id: number) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.delete(id)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        if (!success && body === undefined) {
          this.store.dispatch(new this.baseSetIsLoading(false));
        }
        return of(body);
      }),
      filter((body) => body !== undefined),
      switchMap((body) =>
        this.baseApiService.readByParentId(body.metadata.parentId),
      ),
      switchMap((response) =>
        this.store.dispatch(new this.baseSetItems(response.body)),
      ),
      switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false))),
    );
  }

  moveUp(id: number) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.moveUp(id)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        if (!success && body === undefined) {
          this.store.dispatch(new this.baseSetIsLoading(false));
        }
        return of(body);
      }),
      filter((body) => body !== undefined),
      switchMap((body) =>
        this.baseApiService.readByParentId(body.metadata.parentId),
      ),
      switchMap((response) =>
        this.store.dispatch(new this.baseSetItems(response.body)),
      ),
      switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false))),
    );
  }

  moveDown(id: number) {
    return this.store.dispatch(new this.baseSetIsLoading(true)).pipe(
      switchMap(() => this.baseApiService.moveDown(id)),
      switchMap((response) => {
        const { success, message, body } = response;
        this.store.dispatch(new this.baseSetStatus(success, message));
        if (!success && body === undefined) {
          this.store.dispatch(new this.baseSetIsLoading(false));
        }
        return of(body);
      }),
      filter((body) => body !== undefined),
      switchMap((body) =>
        this.baseApiService.readByParentId(body.metadata.parentId),
      ),
      switchMap((response) =>
        this.store.dispatch(new this.baseSetItems(response.body)),
      ),
      switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false))),
    );
  }
}

import { StateContext } from '@ngxs/store';

import { BaseStoreModel } from '../model/base-store.model';
import { BaseStoreAction } from '../action/base-store.action';

export class BaseStoreState {
  static initState<TItem>(
    columns: BaseStoreModel<TItem>['columns'],
  ): BaseStoreModel<TItem> {
    return {
      success: true,
      message: '',
      isLoading: false,
      items: [],
      columns,
    };
  }

  static baseGetStatus<TItem>(state: BaseStoreModel<TItem>) {
    return {
      success: state.success,
      message: state.message,
    };
  }

  static baseGetIsLoading<TItem>(state: BaseStoreModel<TItem>) {
    return state.isLoading;
  }

  static baseGetItems<TItem>(state: BaseStoreModel<TItem>) {
    return state.items;
  }

  static baseGetSelectedItem<TItem>(state: BaseStoreModel<TItem>) {
    return state.items.find((item) => item.metadata.isSelected);
  }

  static baseGetColumns<TItem>(state: BaseStoreModel<TItem>) {
    return state.columns;
  }

  baseSetStatus<TItem>(
    ctx: StateContext<BaseStoreModel<TItem>>,
    action: BaseStoreAction.SetStatus,
  ) {
    const state = ctx.getState();
    ctx.setState({
      ...state,
      success: action.success,
      message: action.message,
    });
  }

  baseSetIsLoading<TItem>(
    ctx: StateContext<BaseStoreModel<TItem>>,
    action: BaseStoreAction.SetIsLoading,
  ) {
    const state = ctx.getState();
    ctx.setState({
      ...state,
      isLoading: action.isLoading,
    });
  }

  baseSetItems<TItem>(
    ctx: StateContext<BaseStoreModel<TItem>>,
    action: BaseStoreAction.SetItems<TItem>,
  ) {
    const state = ctx.getState();
    ctx.setState({
      ...state,
      items: action.items,
    });
  }
}

